// === Tab: mySketch ===

// let pal = ["#2A9D8F", "#E76A4B", "#235610", "#F25E3F", "#C77F56"];
let pal = ["#E4FDE1", "#8ACB88", "#648381", "#575761", "#FFBF46"];
const N = 100;
const RMAX = 10;
const DIS = 60;
let offset1 = 30;
let offset2 = offset1 / 3;
var c1, c2;
let particles=[];
let t=0.05;
let scale = 0.00001;

function setup() {
  createCanvas(800, 600);
  frameRate(30);
  background(20);

  c1 = pal[int(random(pal.length))];
  c2 = pal[int(random(pal.length))];
  while (c2 == c1) {
    c2 = pal[int(random(pal.length))];
  }
	for(let i=0; i<N; i++) {
		let p = new Particle(random(offset1, width-offset1), random(offset1, height-offset1));
		particles.push(p);
	}
  frame();

}

function draw() {
	// clear();
	frame();

	for(let i=0; i<particles.length; i++) {
		var p = particles[i];
		p.update();
		for(let j=0; j<particles.length; j++) {
			if(j!=i) {
				let o = particles[j];
				if(dist(p.pos.x, p.pos.y, o.pos.x, o.pos.y)<=DIS) {
					line(p.pos.x, p.pos.y, o.pos.x, o.pos.y);
				}
			}
		}
		p.show();
	}
	t+=0.015;

}

class Particle {
	constructor(x, y) {
		this.pos = createVector(x, y);
		this.center = createVector(x, y);
		this.vel = createVector(random(-1,1), random(-1, 1));
		this.vel.normalize().mult(3);
		this.acc = createVector(0, 0);
		// this.acc.sub(this.center);
		this.r = 2;
		this.growth = 1;
	}

	update(){
		// let angle = noise(this.pos.x*scale, this.pos.y*scale, t)*TAU;
		// this.acc = p5.Vector.fromAngle(angle);
		// this.acc.mult(1);
		this.acc = p5.Vector.sub(this.pos, this.center);
		let pull = this.acc.mag();
		let mg = map(pull, 0, sqrt(sq(width)+sq(height)),2,0);
		this.acc.setMag(0.02*mg);
		// this.vel.sub(this.acc);
		this.vel.add(createVector(-this.acc.y, this.acc.x));
		this.vel.limit(3);

		if(this.pos.x<=offset1+1 || this.pos.x>=width-offset1-1) {
			this.vel.x *= (-1);
		}
		if(this.pos.y<=offset1+1 || this.pos.y>=height-offset1-1) {
			this.vel.y *= (-1);
		}
		this.pos.add(this.vel);

		if(this.r >= RMAX || this.r<2) {
			this.growth *= -1;
		}
		this.r += this.growth;
	}

	show() {
		let rgrad = drawingContext.createLinearGradient(
			offset1,
			offset1,
			width-offset1,
			height - offset1
		);
		rgrad.addColorStop(0, c1);
		rgrad.addColorStop(1, c2);
		drawingContext.strokeStyle = rgrad;
		fill(20);
		circle(this.pos.x, this.pos.y, this.r*2);
	}
}



function frame() {
  drawingContext.fillStyle = '#00000';
  drawingContext.globalAlpha = 0.5;
  background(20);
   drawingContext.globalAlpha = 1;
  //Draw a picture frame
  rectMode(CENTER);
  fill(255);
  rect(width / 2, height / 2, width - offset2 * 2, height - offset2 * 2);
  fill(20);
  rect(width / 2, height / 2, width - offset1 * 2, height - offset1 * 2);
	drawingContext.fillStyle = '#00000';
	stroke(20);
	strokeWeight(2);
  line(offset1, offset1, offset2, offset2);
  line(width - offset1, offset1, width - offset2, offset2);
  line(offset1, height - offset1, offset2, height - offset2);
  line(width - offset1, height - offset1, width - offset2, height - offset2);


  let vgrad = drawingContext.createLinearGradient(
    0,
    offset1,
    0,
    height - offset1
  );

  vgrad.addColorStop(0, c1);
  vgrad.addColorStop(1, c2);
  // vgrad.addColorStop(random(1), color(255));
  drawingContext.strokeStyle = vgrad;
  // stroke(150, 50);
  strokeWeight(0.8);
  let step = 25;
  for (let i = offset1; i < width - offset1; i += step) {
    line(i, offset1, i, height - offset1);
  }
  let hgrad = drawingContext.createLinearGradient(
    offset1,
    0,
    width - offset1,
    0
  );
  hgrad.addColorStop(0, c1);
  hgrad.addColorStop(1, c2);
  // hgrad.addColorStop(random(1), color(255));
  drawingContext.strokeStyle = hgrad;
  for (let j = offset1; j < height - offset1; j += step) {
    line(offset1, j, width - offset1, j);
  }

}

